package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.RegisteredEmailTemplateVO;

class RegisteredEmailTemplateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of registered email template of tenant config")
  void test_registered_email_template_value_holder_assign_plain_value() {
    Object holder = new Object();
    RegisteredEmailTemplateValueHolder<Object> value =
        new RegisteredEmailTemplateValueHolder<>(holder);
    Assertions.assertSame(holder, value.registeredEmailTemplate("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRegisteredEmailTemplateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getRegisteredEmailTemplate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.registeredEmailTemplateNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRegisteredEmailTemplateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getRegisteredEmailTemplate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of registered email template of tenant config")
  void test_registered_email_template_value_holder_assign_value_object() {
    Object holder = new Object();
    RegisteredEmailTemplateValueHolder<Object> value =
        new RegisteredEmailTemplateValueHolder<>(holder);
    RegisteredEmailTemplateVO vo = RegisteredEmailTemplateVO.from("one");
    Assertions.assertFalse(value.getRegisteredEmailTemplateValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.registeredEmailTemplate(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getRegisteredEmailTemplateValue().orElseThrow());
    Assertions.assertSame(holder, value.registeredEmailTemplate(Optional.empty()));
    Assertions.assertFalse(value.getRegisteredEmailTemplateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.registeredEmailTemplate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRegisteredEmailTemplateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of registered email template of tenant config against the original")
  void test_registered_email_template_value_holder_read() {
    Object holder = new Object();
    RegisteredEmailTemplateValueHolder<Object> value =
        new RegisteredEmailTemplateValueHolder<>(holder);
    RegisteredEmailTemplateVO vo = RegisteredEmailTemplateVO.from("one");
    RegisteredEmailTemplateVO other = RegisteredEmailTemplateVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getRegisteredEmailTemplateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRegisteredEmailTemplate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRegisteredEmailTemplate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.registeredEmailTemplate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRegisteredEmailTemplate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRegisteredEmailTemplate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of registered email template of tenant config")
  void test_registered_email_template_value_holder_unset() {
    Object holder = new Object();
    RegisteredEmailTemplateValueHolder<Object> value =
        new RegisteredEmailTemplateValueHolder<>(holder);
    RegisteredEmailTemplateVO vo = RegisteredEmailTemplateVO.from("one");
    value.registeredEmailTemplate(vo);
    Assertions.assertSame(holder,
        value.unsetRegisteredEmailTemplateIfMatches("registeredEmailTemplate_other"));
    Assertions.assertTrue(value.getRegisteredEmailTemplateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetRegisteredEmailTemplateIfMatches("registeredEmailTemplate"));
    Assertions.assertFalse(value.getRegisteredEmailTemplateValue().isPresent(),
        "The field name must clear the value");
    value.registeredEmailTemplate(vo);
    Assertions.assertSame(holder, value.unsetRegisteredEmailTemplate());
    Assertions.assertFalse(value.getRegisteredEmailTemplateValue().isPresent(),
        "Unset must clear the value");
  }
}
